157: //process XML file contents
158: int expat_process_zip_file (ZIPFILETYPE* zip, const XML_Char* filename, XML_StartElementHandler start_handler, XML_EndElementHandler end_handler, XML_CharacterDataHandler data_handler, void* callbackdata, XML_Parser* xmlparser)
159: {
160:   ZIPFILEENTRYTYPE* zipfile;
161:   XML_Parser parser;
162:   void* buf;
163: #ifdef USE_MINIZIP
164:   int buflen;
165: #else
166:   zip_int64_t buflen;
167: #endif
168:   int done;
169:   enum XML_Status status = XML_STATUS_ERROR;
170:   if ((zipfile = XML_Char_openzip(zip, filename, 0)) == NULL) {
171:     return -1;
172:   }
173:   parser = XML_ParserCreate(NULL);
174:   XML_SetUserData(parser, callbackdata);
175:   XML_SetElementHandler(parser, start_handler, end_handler);
176:   XML_SetCharacterDataHandler(parser, data_handler);
177:   if (xmlparser)
178:     *xmlparser = parser;
179:   buf = XML_GetBuffer(parser, PARSE_BUFFER_SIZE);
180: #ifdef USE_MINIZIP
181:     while (buf && (buflen = unzReadCurrentFile(zip, buf, PARSE_BUFFER_SIZE)) >= 0) {
182: #else
183:     while (buf && (buflen = zip_fread(zipfile, buf, PARSE_BUFFER_SIZE)) >= 0) {
184: #endif
185:       done = buflen < PARSE_BUFFER_SIZE;
186:       if ((status = XML_ParseBuffer(parser, (int)buflen, (done ? 1 : 0))) == XML_STATUS_ERROR) {
187:         break;
188:       }
189:       if (xmlparser && status == XML_STATUS_SUSPENDED)
190:         return 0;
191:       if (done)
192:         break;
193:       buf = XML_GetBuffer(parser, PARSE_BUFFER_SIZE);
194:     }
195:   XML_ParserFree(parser);
196: #ifdef USE_MINIZIP
197:   unzCloseCurrentFile(zip);
198: #else
199:   zip_fclose(zipfile);
200: #endif
201:   //return (status == XML_STATUS_ERROR != XML_ERROR_FINISHED ? 1 : 0);
202:   return 0;
203: }
