250: //compare XML name ignoring case and ignoring namespace (returns 0 on match)
251: #ifdef ASSUME_NO_NAMESPACE
252: #define XML_Char_icmp_ins XML_Char_icmp
253: #else
254: int XML_Char_icmp_ins (const XML_Char* value, const XML_Char* name)
255: {
256:   size_t valuelen;
257:   size_t namelen;
258:   if (!value)
259:     return (!name ? 0 : -1);
260:   if (!name)
261:     return -1;
262:   valuelen = XML_Char_len(value);
263:   namelen = XML_Char_len(name);
264:   if (valuelen == namelen)
265:     return XML_Char_icmp(value, name);
266:   if (valuelen > namelen) {
267:     if (value[valuelen - namelen - 1] != ':')
268:       return 1;
269:     return XML_Char_icmp(value + (valuelen - namelen), name);
270:   }
271:   return -1;
272: }
273: #endif
