290: //generate .rels filename, returns NULL on error, caller must free result
291: XML_Char* get_relationship_filename (const XML_Char* filename)
292: {
293:   XML_Char* result;
294:   size_t filenamelen = XML_Char_len(filename);
295:   if ((result = XML_Char_malloc(filenamelen + 12)) != NULL) {
296:     size_t i = filenamelen;
297:     while (i > 0) {
298:       if (filename[i - 1] == '/')
299:         break;
300:       i--;
301:     }
302:     XML_Char_poscpy(result, 0, filename, i);
303:     XML_Char_poscpy(result, i, X("_rels/"), 6);
304:     XML_Char_poscpy(result, i + 6, filename + i, filenamelen - i);
305:     XML_Char_poscpy(result, filenamelen + 6, X(".rels"), 6);
306:   }
307:   return result;
308: }
