310: //join basepath and filename (caller must free result)
311: XML_Char* join_basepath_filename (const XML_Char* basepath, const XML_Char* filename)
312: {
313:   XML_Char* result = NULL;
314:   if (filename && *filename) {
315:     if (filename[0] == '/' && filename[1]) {
316:       //file is absolute: remove leading slash
317:       result = XML_Char_dup(filename + 1);
318:     } else {
319:       //file is relative: prepend base path
320:       size_t basepathlen = (basepath ? XML_Char_len(basepath) : 0);
321:       size_t filenamelen = XML_Char_len(filename);
322:       if ((result = XML_Char_malloc(basepathlen + filenamelen + 1)) != NULL) {
323:         if (basepathlen > 0)
324:           XML_Char_poscpy(result, 0, basepath, basepathlen);
325:         XML_Char_poscpy(result, basepathlen, filename, filenamelen);
326:         result[basepathlen + filenamelen] = 0;
327:       }
328:     }
329:   }
330:   return result;
331: }
