333: //determine column number based on cell coordinate (e.g. "A1"), returns 1-based column number or 0 on error
334: size_t get_col_nr (const XML_Char* A1col)
335: {
336:   const XML_Char* p = A1col;
337:   size_t result = 0;
338:   if (p) {
339:     while (*p) {
340:       if (*p >= 'A' && *p <= 'Z')
341:         result = result * 26 + (*p - 'A') + 1;
342:       else if (*p >= 'a' && *p <= 'z')
343:         result = result * 26 + (*p - 'a') + 1;
344:       else if (*p >= '0' && *p <= '9' && p != A1col)
345:         return result;
346:       else
347:         break;
348:       p++;
349:     }
350:   }
351:   return 0;
352: }
