354: //determine row number based on cell coordinate (e.g. "A1"), returns 1-based row number or 0 on error
355: size_t get_row_nr (const XML_Char* A1col)
356: {
357:   const XML_Char* p = A1col;
358:   size_t result = 0;
359:   if (p) {
360:     while (*p) {
361:       if ((*p >= 'A' && *p <= 'Z') || (*p >= 'a' && *p <= 'z'))
362:         ;
363:       else if (*p >= '0' && *p <= '9' && p != A1col)
364:         result = result * 10 + (*p - '0');
365:       else
366:         return 0;
367:       p++;
368:     }
369:   }
370:   return result;
371: }
