670: //expat callback function for element start used by iterate_files_by_contenttype
671: void iterate_files_by_contenttype_expat_callback_element_start (void* callbackdata, const XML_Char* name, const XML_Char** atts)
672: {
673:   struct iterate_files_by_contenttype_callback_data* data = (struct iterate_files_by_contenttype_callback_data*)callbackdata;
674:   if (XML_Char_icmp_ins(name, X("Override")) == 0) {
675:     //explicitly specified file
676:     const XML_Char* contenttype;
677:     const XML_Char* partname;
678:     if ((contenttype = get_expat_attr_by_name(atts, X("ContentType"))) != NULL && XML_Char_icmp(contenttype, data->contenttype) == 0) {
679:       if ((partname = get_expat_attr_by_name(atts, X("PartName"))) != NULL) {
680:         if (partname[0] == '/')
681:           partname++;
682:         data->filecallbackfn(data->zip, partname, contenttype, data->filecallbackdata);
683:       }
684:     }
685:   } else if (XML_Char_icmp_ins(name, X("Default")) == 0) {
686:     //by extension
687:     // NOTE: expat_process_zip_file has already opened [Content_Types].xml via
688:     // unzOpenCurrentFile and is streaming it when this callback runs. On the
689:     // minizip backend the code below traverses the zip central directory
690:     // (unzGoToFirstFile / unzGetCurrentFileInfo / unzGoToNextFile) on the same
691:     // unzFile handle, which corrupts minizip's single state machine and crashes
692:     // in unzGetCurrentFileInfo (issue #28). Legitimate xlsx files always declare
693:     // the main/sheet content type via <Override>, never <Default>, so this branch
694:     // never matches for the content types xlsxio looks up. Skip it on the minizip
695:     // backend at compile time; the libzip backend (index-based zip_get_name) is
696:     // unaffected and keeps its original logic.
697: #ifndef USE_MINIZIP /* !USE_MINIZIP: skip <Default> branch to avoid minizip state clash */
698:     const XML_Char* contenttype;
699:     const XML_Char* extension;
700:     if ((contenttype = get_expat_attr_by_name(atts, X("ContentType"))) != NULL && XML_Char_icmp(contenttype, data->contenttype) == 0) {
701:       if ((extension = get_expat_attr_by_name(atts, X("Extension"))) != NULL) {
702:         XML_Char* filename;
703:         size_t filenamelen;
704:         size_t extensionlen = XML_Char_len(extension);
705: #ifdef USE_MINIZIP
706: #define UNZIP_FILENAME_BUFFER_STEP 32
707:         char* buf;
708:         size_t buflen;
709:         int status;
710: unz_global_info zipglobalinfo;
711: unzGetGlobalInfo(data->zip, &zipglobalinfo);
712:         buf = (char*)malloc(buflen = UNZIP_FILENAME_BUFFER_STEP);
713:         status = unzGoToFirstFile(data->zip);
714:         while (status == UNZ_OK) {
715:           buf[buflen - 1] = 0;
716:           while ((status = unzGetCurrentFileInfo(data->zip, NULL, buf, buflen, NULL, 0, NULL, 0)) == UNZ_OK && buf[buflen - 1] != 0) {
717:             buflen += UNZIP_FILENAME_BUFFER_STEP;
718:             if ((buf = (char*)realloc(buf, buflen)) == NULL) {
719:               //memory allocation error
720:               return;
721:             }
722:             buf[buflen - 1] = 0;
723:           }
724:           if (status != UNZ_OK)
725:             break;
726:           filename = XML_Char_dupchar(buf);
727:           status = unzGoToNextFile(data->zip);
728: #else
729:         zip_int64_t i;
730:         zip_int64_t zipnumfiles = zip_get_num_entries(data->zip, 0);
731:         for (i = 0; i < zipnumfiles; i++) {
732:           filename = XML_Char_dupchar(zip_get_name(data->zip, i, ZIP_FL_ENC_GUESS));
733: #endif
734:           filenamelen = XML_Char_len(filename);
735:           if (filenamelen > extensionlen && filename[filenamelen - extensionlen - 1] == '.' && XML_Char_icmp(filename + filenamelen - extensionlen, extension) == 0) {
736:             data->filecallbackfn(data->zip, filename, contenttype, data->filecallbackdata);
737:           }
738:           free(filename);
739:         }
740: #ifdef USE_MINIZIP
741:         free(buf);
742: #endif
743:       }
744:     }
745: #endif /* !USE_MINIZIP: skip <Default> branch to avoid minizip state clash */
746:   }
747: }
