881: //determine the file name for a specified sheet name
882: void main_sheet_get_sheetfile_callback (ZIPFILETYPE* zip, const XML_Char* filename, const XML_Char* contenttype, void* callbackdata)
883: {
884:   struct main_sheet_get_rels_callback_data* data = (struct main_sheet_get_rels_callback_data*)callbackdata;
885:   if (!data->sheetrelid) {
886:     expat_process_zip_file(zip, filename, main_sheet_get_relid_expat_callback_element_start, NULL, NULL, callbackdata, &data->xmlparser);
887:   }
888:   if (data->sheetrelid) {
889:     XML_Char* relfilename;
890:     //determine base name (including trailing slash)
891:     size_t i = XML_Char_len(filename);
892:     while (i > 0) {
893:       if (filename[i - 1] == '/')
894:         break;
895:       i--;
896:     }
897:     if (data->basepath)
898:       free(data->basepath);
899:     if ((data->basepath = XML_Char_malloc(i + 1)) != NULL) {
900:       XML_Char_poscpy(data->basepath, 0, filename, i);
901:       data->basepath[i] = 0;
902:     }
903:     //find sheet filename in relationship contents
904:     if ((relfilename = get_relationship_filename(filename)) != NULL) {
905:       expat_process_zip_file(zip, relfilename, main_sheet_get_sheetfile_expat_callback_element_start, NULL, NULL, callbackdata, &data->xmlparser);
906:       free(relfilename);
907:     } else {
908:       free(data->sheetrelid);
909:       data->sheetrelid = NULL;
910:       if (data->basepath) {
911:         free(data->basepath);
912:         data->basepath = NULL;
913:       }
914:     }
915:   }
916: }
