1048: void data_sheet_expat_callback_find_row_start (void* callbackdata, const XML_Char* name, const XML_Char** atts)
1049: {
1050:   struct data_sheet_callback_data* data = (struct data_sheet_callback_data*)callbackdata;
1051:   if (XML_Char_icmp_ins(name, X("row")) == 0) {
1052:     const XML_Char* hidden = get_expat_attr_by_name(atts, X("hidden"));
1053:     if (!(hidden && XML_Char_tol(hidden) != 0 && (data->flags & XLSXIOREAD_SKIP_HIDDEN_ROWS))) {
1054:       int skippedemptyrow = (data->rownr != 0 && data->colsnotnull == 0 && (data->flags & XLSXIOREAD_SKIP_EMPTY_ROWS));
1055:       data->rownr++;
1056:       data->colnr = 0;
1057:       data->colsnotnull = 0;
1058:       XML_SetElementHandler(data->xmlparser, data_sheet_expat_callback_find_cell_start, data_sheet_expat_callback_find_row_end);
1059:       //for non-calback method suspend here on new row
1060:       if (data->flags & XLSXIOREAD_NO_CALLBACK) {
1061:         if (!skippedemptyrow) {
1062:           XML_StopParser(data->xmlparser, XML_TRUE);
1063:         }
1064:       }
1065:     } else {
1066:       //skip hidden row
1067:       XML_SetElementHandler(data->xmlparser, NULL, data_sheet_expat_callback_find_row_end);
1068:     }
1069:   }
1070: }
