1072: void data_sheet_expat_callback_find_row_end (void* callbackdata, const XML_Char* name)
1073: {
1074:   struct data_sheet_callback_data* data = (struct data_sheet_callback_data*)callbackdata;
1075:   if (XML_Char_icmp_ins(name, X("row")) == 0) {
1076:     //determine number of columns based on first row
1077:     if ((data->flags & XLSXIOREAD_SKIP_EXTRA_CELLS) && data->rownr == 1 && data->cols == 0)
1078:       data->cols = data->colnr;
1079:     //add empty columns if needed
1080:     if (!(data->flags & XLSXIOREAD_NO_CALLBACK) && data->sheet_cell_callback && !(data->flags & XLSXIOREAD_SKIP_EMPTY_CELLS)) {
1081:       while (data->colnr < data->cols) {
1082:         if ((*data->sheet_cell_callback)(data->rownr, data->colnr + 1, NULL, data->callbackdata)) {
1083:           XML_StopParser(data->xmlparser, XML_FALSE);
1084:           return;
1085:         }
1086:         data->colnr++;
1087:       }
1088:     }
1089:     free(data->celldata);
1090:     data->celldata = NULL;
1091:     XML_SetElementHandler(data->xmlparser, data_sheet_expat_callback_find_row_start, data_sheet_expat_callback_find_sheetdata_end);
1092:     //process end of row
1093:     if (!(data->flags & XLSXIOREAD_NO_CALLBACK)) {
1094:       if (data->sheet_row_callback && !(data->colsnotnull == 0 && (data->flags & XLSXIOREAD_SKIP_EMPTY_ROWS))) {
1095:         if ((*data->sheet_row_callback)(data->rownr, data->colnr, data->callbackdata)) {
1096:           XML_StopParser(data->xmlparser, XML_FALSE);
1097:           return;
1098:         }
1099:       }
1100:     } else {
1101:       //for non-calback method suspend here on end of row
1102:       if (!(data->colsnotnull == 0 && (data->flags & XLSXIOREAD_SKIP_EMPTY_ROWS)))
1103:         XML_StopParser(data->xmlparser, XML_TRUE);
1104:     }
1105:   } else {
1106:     data_sheet_expat_callback_find_sheetdata_end(callbackdata, name);
1107:   }
1108: }
