1110: void data_sheet_expat_callback_find_cell_start (void* callbackdata, const XML_Char* name, const XML_Char** atts)
1111: {
1112:   struct data_sheet_callback_data* data = (struct data_sheet_callback_data*)callbackdata;
1113:   if (XML_Char_icmp_ins(name, X("c")) == 0) {
1114:     const XML_Char* t = get_expat_attr_by_name(atts, X("r"));
1115:     size_t cellcolnr = get_col_nr(t);
1116:     //insert empty rows if needed
1117:     if (data->colnr == 0) {
1118:       size_t cellrownr = get_row_nr(t);
1119:       if (cellrownr) {
1120:         if (!(data->flags & XLSXIOREAD_SKIP_EMPTY_ROWS) && !(data->flags & XLSXIOREAD_NO_CALLBACK)) {
1121:           while (data->rownr < cellrownr) {
1122:             //insert empty columns
1123:             if (!(data->flags & XLSXIOREAD_SKIP_EMPTY_CELLS) && data->sheet_cell_callback) {
1124:               while (data->colnr < data->cols) {
1125:                 if ((*data->sheet_cell_callback)(data->rownr, data->colnr + 1, NULL, data->callbackdata)) {
1126:                   XML_StopParser(data->xmlparser, XML_FALSE);
1127:                   return;
1128:                 }
1129:                 data->colnr++;
1130:               }
1131:             }
1132:             //finish empty row
1133:             if (data->sheet_row_callback) {
1134:               if ((*data->sheet_row_callback)(data->rownr, data->cols, data->callbackdata)) {
1135:                 XML_StopParser(data->xmlparser, XML_FALSE);
1136:                 return;
1137:               }
1138:             }
1139:             data->rownr++;
1140:             data->colnr = 0;
1141:           }
1142:         } else {
1143:           data->rownr = cellrownr;
1144:         }
1145:       }
1146:     }
1147:     //insert empty columns if needed
1148:     if (cellcolnr) {
1149:       cellcolnr--;
